import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import {
  mkdtempSync, mkdirSync, writeFileSync, readFileSync, readdirSync,
  existsSync, rmSync,
} from "node:fs";
import { join, dirname } from "node:path";
import { pathToFileURL } from "node:url";
import { execFileSync, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";

const REPO_ROOT = dirname(dirname(dirname(new URL(import.meta.url).pathname)));
const STAGE_ROOT = join(REPO_ROOT, ".pi-test-release");
const PKG_VERSION = "0.3.1"; // bump alongside the version node

function sha256(buf: Buffer): string {
  return createHash("sha256").update(buf).digest("hex");
}

function listExtensionsUnderAssets(assetsRoot: string): string[] {
  const extDir = join(assetsRoot, "assets", ".pi", "extensions");
  return readdirSync(extDir, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
    .sort();
}

describe("L4 release: npm pack → install lands every extension in assets/.pi/extensions/", () => {
  const tarballPath = join(STAGE_ROOT, `pisquad-${PKG_VERSION}.tgz`);
  const extractedRoot = join(STAGE_ROOT, "extracted");
  const target = join(STAGE_ROOT, "target");
  const distBin = join(extractedRoot, "package", "dist", "bin.js");

  before(() => {
    rmSync(STAGE_ROOT, { recursive: true, force: true });
    mkdirSync(STAGE_ROOT, { recursive: true });
    // Build the tarball from the current source tree. `tsup` is required
    // because the package's `files` list includes `dist/` but it may be
    // stale; rebuild to be safe.
    execFileSync("npm", ["run", "build"], { cwd: REPO_ROOT, stdio: "inherit" });
    // npm pack writes the tarball at the cwd; pin output path with --pack-destination.
    execFileSync("npm", ["pack", "--pack-destination", STAGE_ROOT], {
      cwd: REPO_ROOT,
      stdio: "inherit",
    });
    // npm pack names the tarball @nicklin-pisquad-<version>.tgz (scoped).
    // Locate it under STAGE_ROOT and rename for determinism.
    const files = readdirSync(STAGE_ROOT).filter((f) => f.endsWith(".tgz"));
    assert.equal(files.length, 1, `expected exactly one tarball, got ${files.join(", ")}`);
    const { renameSync } = require("node:fs");
    renameSync(join(STAGE_ROOT, files[0]), tarballPath);
    // Extract. `tar -xzf` is universally available; matches the existing
    // tarball convention in test/upgrade/integration.test.ts.
    execFileSync("tar", ["-xzf", tarballPath, "-C", extractedRoot], { stdio: "inherit" });
    assert.ok(existsSync(distBin), `dist/bin.js missing after extract at ${distBin}`);
  });

  after(() => {
    try {
      rmSync(STAGE_ROOT, { recursive: true, force: true });
    } catch { /* best-effort */ }
  });

  it("install --yes lands every assets/.pi/extensions/* entry under target/.pi/extensions/", () => {
    // Sanity: assets has 5 extension dirs (subagent, wikilink-lint, bash-guard, codegraph, entire).
    // Core install ships 3 (subagent, wikilink-lint, bash-guard).
    // The bug: bash-guard is missing pre-fix. We assert EVERY entry the
    // package ships under assets/.pi/extensions/ that's part of core lands
    // under target/.pi/extensions/. (We don't assert codegraph/entire here
    // because they're optional channels requiring host CLIs.)
    const assetsExt = listExtensionsUnderAssets(join(extractedRoot, "package"));
    const CORE_EXTS = ["subagent", "wikilink-lint", "bash-guard"];
    for (const name of CORE_EXTS) {
      assert.ok(assetsExt.includes(name), `assets missing ${name}; can't validate install`);
    }

    // Fresh target.
    rmSync(target, { recursive: true, force: true });
    mkdirSync(target, { recursive: true });

    // Spawn the extracted dist CLI. No `pisquad` on PATH so selfUpdate
    // short-circuits; PISQUAD_NO_SELF=1 belt-and-suspenders.
    const res = spawnSync(process.execPath, [distBin, "install", "--yes", target], {
      env: { ...process.env, PISQUAD_NO_SELF: "1", NO_COLOR: "1" },
      encoding: "utf8",
      timeout: 180_000, // 3 min, plenty for a core install
    });
    assert.equal(res.status, 0, `install failed:\nSTDOUT:\n${res.stdout}\nSTDERR:\n${res.stderr}`);

    // Every core extension directory must exist in target.
    for (const name of CORE_EXTS) {
      const targetDir = join(target, ".pi", "extensions", name);
      assert.ok(existsSync(targetDir), `install missed extension: ${name}`);
    }

    // The bash-guard file content must byte-match the assets version.
    const srcContent = readFileSync(
      join(extractedRoot, "package", "assets", ".pi", "extensions", "bash-guard", "index.ts"),
    );
    const dstContent = readFileSync(
      join(target, ".pi", "extensions", "bash-guard", "index.ts"),
    );
    assert.equal(
      sha256(srcContent),
      sha256(dstContent),
      "bash-guard/index.ts content differs between assets and target after install",
    );

    // Strongest check: every entry the package ships under assets/.pi/extensions/
    // that's in the core-managed set (subagent, wikilink-lint, bash-guard) is
    // present in target with identical sha256.
    for (const name of CORE_EXTS) {
      const srcDir = join(extractedRoot, "package", "assets", ".pi", "extensions", name);
      const dstDir = join(target, ".pi", "extensions", name);
      assertExtensionsEqual(srcDir, dstDir, name);
    }
  });

  it("install path dynamic-imports the dropped bash-guard entry without Cannot find module", async () => {
    // Pre-condition: install already ran in the previous test (target is
    // populated). Run install again to be independent — but skip if the
    // prior test failed.
    if (!existsSync(join(target, ".pi", "extensions", "bash-guard", "index.ts"))) {
      // Re-run install in case this test runs in isolation.
      const res = spawnSync(process.execPath, [distBin, "install", "--yes", target], {
        env: { ...process.env, PISQUAD_NO_SELF: "1", NO_COLOR: "1" },
        encoding: "utf8",
        timeout: 180_000,
      });
      assert.equal(res.status, 0, `install re-run failed:\n${res.stderr}`);
    }
    const entry = join(target, ".pi", "extensions", "bash-guard", "index.ts");
    assert.ok(existsSync(entry), `entry missing: ${entry}`);
    let mod: unknown;
    try {
      mod = await import(pathToFileURL(entry).href);
    } catch (error) {
      assert.fail(`dynamic import of ${entry} threw: ${error instanceof Error ? error.message : String(error)}`);
    }
    // Sanity: the module's default export is the ExtensionAPI handler factory.
    assert.equal(typeof (mod as { default?: unknown }).default, "function",
      "bash-guard default export should be a function (ExtensionAPI handler factory)");
  });

  it("upgrade (no network) also lands bash-guard on a fresh install", () => {
    // Reset target; install; then upgrade. Self-update is skipped because
    // the dist CLI is invoked directly via `node`, not via `pisquad` on PATH.
    const fresh = join(STAGE_ROOT, "target-upgrade");
    rmSync(fresh, { recursive: true, force: true });
    mkdirSync(fresh, { recursive: true });

    // Stage 1: install --yes.
    const installRes = spawnSync(process.execPath, [distBin, "install", "--yes", fresh], {
      env: { ...process.env, PISQUAD_NO_SELF: "1", NO_COLOR: "1" },
      encoding: "utf8",
      timeout: 180_000,
    });
    assert.equal(installRes.status, 0, `install (upgrade path) failed:\n${installRes.stderr}`);

    // Stage 2: upgrade.
    const upgradeRes = spawnSync(process.execPath, [distBin, "upgrade", fresh], {
      env: { ...process.env, PISQUAD_NO_SELF: "1", NO_COLOR: "1" },
      encoding: "utf8",
      timeout: 180_000,
    });
    assert.equal(upgradeRes.status, 0, `upgrade failed:\nSTDOUT:\n${upgradeRes.stdout}\nSTDERR:\n${upgradeRes.stderr}`);

    // bash-guard still present, still byte-matching.
    const entry = join(fresh, ".pi", "extensions", "bash-guard", "index.ts");
    assert.ok(existsSync(entry), `upgrade dropped bash-guard: ${entry}`);
    const srcContent = readFileSync(
      join(extractedRoot, "package", "assets", ".pi", "extensions", "bash-guard", "index.ts"),
    );
    const dstContent = readFileSync(entry);
    assert.equal(sha256(srcContent), sha256(dstContent),
      "upgrade changed bash-guard/index.ts content unexpectedly");

    // state.json sanity: lastUpgradedAt is set, version matches bump.
    const stateRaw = readFileSync(join(fresh, ".pi", ".pisquad", "state.json"), "utf8");
    const state = JSON.parse(stateRaw) as { version?: string; lastUpgradedAt?: string };
    assert.equal(state.version, PKG_VERSION, "state.json version should match bumped assets-version");
    assert.ok(typeof state.lastUpgradedAt === "string" && state.lastUpgradedAt.length > 0,
      `lastUpgradedAt should be set after upgrade; got: ${state.lastUpgradedAt}`);
  });
});

/** Recursively assert that two extension directories have identical file trees
 *  and byte-identical content. Used to fail loudly if the install left
 *  anything behind (e.g. missing bash-guard). */
function assertExtensionsEqual(srcDir: string, dstDir: string, name: string): void {
  const files: string[] = [];
  const walk = (dir: string, rel: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const childRel = rel ? `${rel}/${entry.name}` : entry.name;
      const childAbs = join(dir, entry.name);
      if (entry.isDirectory()) walk(childAbs, childRel);
      else if (entry.isFile()) files.push(childRel);
    }
  };
  walk(srcDir, "");
  for (const rel of files) {
    const a = readFileSync(join(srcDir, rel));
    const b = readFileSync(join(dstDir, rel));
    assert.equal(sha256(a), sha256(b),
      `extension ${name}: file ${rel} differs between assets and target`);
  }
}
