/**
 * `pisquad upgrade` — sync a target install with the assets bundled in this
 * CLI package. See `docs/tasks/pisquad-cli/11-upgrade-command.md` for the full
 * behavioural contract.
 */
export async function upgradeCommand(options: UpgradeOptions): Promise<void> {
  const target = resolveTarget(options.target);
  const dryRun = options.dryRun === true;
  logger.info(`pisquad upgrade → ${target}${dryRun ? " (dry-run)" : ""}`);

  // 1. CLI self-update — if we actually upgraded the global CLI, the in-memory
  //    code is stale; tell the user to re-run and exit cleanly.
  let selfResult;
  try {
    selfResult = await selfUpdate({ logger, noSelf: options.noSelf });
  } catch (error) {
    logger.error(
      `CLI self-update failed: ${error instanceof Error ? error.message : String(error)}`,
    );
    process.exitCode = 1;
    return;
  }
  if (selfResult.updated) {
    logger.success(
      "CLI self-updated to latest. Re-run `pisquad upgrade` to sync this project with the new version.",
    );
    return;
  }

  // 2. Require an existing install — legacy bash-installed projects have no
  //    state.json and must reinstall (PRD non-goal #1).
  let state: InstallState;
  try {
    state = requireState(target);
  } catch (error) {
    if (error instanceof StateMissingError) {
      logger.error(error.message);
      process.exitCode = 1;
      return;
    }
    throw error;
  }

  // 3. Decide the post-upgrade channel set: state baseline + flags.
  let newChannels;
  try {
    newChannels = mergeChannels(state.channels, options);
  } catch (error) {
    logger.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
    return;
  }
  const cliVersion = readCliVersion();
  const assetsVersion = readAssetsVersion();
  const versionDiff = compareVersions(state, {
    version: assetsVersion,
    cliVersion,
    channels: newChannels,
  });

  // 4. Build the diff include list (subtree granularity, never the whole .pi/).
  //    The includes are intentionally narrow so .pi/assets-version.txt and
  //    .pi/.gitignore (root files) never enter the diff.
  //
  //    `interactive: true` flags user-editable territory (docs, agents,
  //    skills). These are eligible for per-file prompts in
  //    `resolveUpgradeActions`. Extension packages are managed by the
  //    pisquad release process — they are always overwritten, never
  //    presented for per-file adoption.
  //
  //    Core extension subtrees are projected from `EXTENSION_DIRS`
  //    (single source of truth in `src/lib/plugins/core.ts`) so a new
  //    core extension added there automatically lands in the upgrade
  //    diff — preventing the 0.3.1 silent-degradation bug where
  //    `bash-guard` was installed but never reached via `upgrade`.
  //    Entries inside EXTENSION_DIRS are `.pi`-relative (e.g.
  //    `extensions/subagent`), so we prepend `.pi/` here to form the
  //    `PkgInclude` paths the diff layer expects.
  const includes: PkgInclude[] = [
    { pkgSubPath: ".pi/agents", targetSubPath: ".pi/agents", interactive: true },
    { pkgSubPath: ".pi/skills", targetSubPath: ".pi/skills", interactive: true },
    ...Array.from(EXTENSION_DIRS).map(
      (sub): PkgInclude => ({
        pkgSubPath: `.pi/${sub}`,
        targetSubPath: `.pi/${sub}`,
      }),
    ),
    { pkgSubPath: "docs", targetSubPath: "docs", interactive: true },
  ];
  if (newChannels.codegraph) {
    includes.push({
      pkgSubPath: ".pi/extensions/codegraph",
      targetSubPath: ".pi/extensions/codegraph",
    });
  }
  if (newChannels.entire) {
    includes.push({
      pkgSubPath: ".pi/extensions/entire",
      targetSubPath: ".pi/extensions/entire",
    });
  }

  // 5. Compute the diff plan.
  const plan = await diffTree(target, includes);

  if (versionDiff.versionChanged) {
    logger.info(`assets version: ${state.version} → ${assetsVersion}`);
  }
  if (versionDiff.cliVersionChanged) {
    logger.info(`CLI version: ${state.cliVersion} → ${cliVersion}`);
  }
  if (versionDiff.newChannels.length > 0) {
    logger.info(`new channels: ${versionDiff.newChannels.join(", ")}`);
  }
  if (versionDiff.removedChannels.length > 0) {
    logger.info(`removed channels: ${versionDiff.removedChannels.join(", ")}`);
  }

  // 6. Dry-run: print the plan and stop before any writes. We still run
  //    `resolveUpgradeActions` here (in non-interactive mode) so the user
  //    sees a decision preview alongside the raw plan — counts of how many
  //    files would be adopted, kept, removed, and backed up under the
  //    active flags. `resolveUpgradeActions` is pure (no FS or editor side
  //    effects) so this is safe in dry-run. When the plan is empty we skip
  //    the decision layer entirely; there is nothing to summarise.
  if (dryRun) {
    const planIsEmpty =
      plan.modified.length === 0 && plan.added.length === 0 && plan.removed.length === 0;
    if (!planIsEmpty) {
      // Force non-interactive: no prompts will fire, the all-adopt default
      // applies, and we never call createBackup from this path.
      const dryRunDecision = await resolveUpgradeActions(
        {
          plan,
          includes,
          target,
          prune: options.prune === true,
          interactive: false,
          interactiveSetByUser: true,
          isInteractiveEnv: false,
          yes: true,
        },
        options.decisionDeps ?? buildDefaultDecisionDeps(target, resolveAsset("")),
      );
      const adoptCount = dryRunDecision.adopt.size;
      const keepCount = dryRunDecision.keep.size;
      const editCount = dryRunDecision.editResults.length;
      const backupCount = dryRunDecision.backup.size;
      const removeCount = dryRunDecision.remove.size;
      logger.info(
        `Would adopt: ${adoptCount} / keep: ${keepCount} / edit: ${editCount} / backup: ${backupCount} / remove: ${removeCount}`,
      );
    }
    printPlan(plan, options.prune === true);
    logger.info("DRY RUN — no changes made");
    return;
  }

  // 7. Run the decision layer. Interactive mode requires BOTH:
  //    a. The caller didn't pass `--no-interactive` or `--yes`.
  //    b. The host has a real tty (and is not CI / PISQUAD_NO_TTY).
  //
  //    Without both, we silently fall through to the all-adopt default —
  //    preserving the legacy "no tty → batch overwrite" behaviour. The
  //    decision layer is wrapped in its own try/catch so that a Ctrl-C
  //    inside @inquirer/prompts (an ExitPromptError) leaves the target
  //    untouched and exits with code 1.
  const isInteractiveEnv =
    options.yes !== true &&
    options.interactive !== false &&
    (options.forceInteractiveEnv === true || isInteractive());
  // Heads-up: the user explicitly asked for `--interactive` but we have no
  // tty (or they used `--yes`). Without this warning the command would
  // silently downgrade to batch adopt, which is surprising for someone
  // who reached for the flag. Skip the warning when forceInteractiveEnv
  // is in play (test seam) so CI-driven suites don't see noise.
  if (
    options.forceInteractiveEnv !== true &&
    options.interactiveSetByUser === true &&
    options.interactive === true &&
    !isInteractiveEnv
  ) {
    logger.warn(
      "--interactive ignored: no TTY detected, falling back to non-interactive (adopt-new) mode",
    );
  }
  let decision: ResolvedPlan;
  try {
    decision = await resolveUpgradeActions(
      {
        plan,
        includes,
        target,
        prune: options.prune === true,
        // Must stay `=== true`: an absent flag (`undefined`) must reach the
        // decision layer as `false` so shouldPrompt's interactiveSetByUser
        // guard distinguishes "absent" from explicit `--no-interactive`.
        interactive: options.interactive === true,
        interactiveSetByUser: options.interactiveSetByUser === true,
        isInteractiveEnv,
        yes: options.yes === true,
      },
      options.decisionDeps ?? buildDefaultDecisionDeps(target, resolveAsset("")),
    );
  } catch (error) {
    // Distinguish two failure modes: a user-initiated cancellation (Ctrl-C
    // → @inquirer/core's ExitPromptError) is not a fault; surface it
    // honestly. Anything else is a real exception in the decision layer
    // (e.g. diff CLI failure, editor crash, FS error) — call it a failure
    // so the user can debug. Both still leave the target untouched
    // because the decision layer runs before the backup stage.
    const isUserCancel =
      error instanceof ExitPromptError ||
      (error instanceof Error && error.name === "ExitPromptError");
    if (isUserCancel) {
      logger.error("user cancelled — no changes made, no backup created");
    } else {
      const message = error instanceof Error ? error.message : String(error);
      logger.error(`upgrade failed during decision: ${message}`);
    }
    process.exitCode = 1;
    return;
  }

  // 8. Back up files the decision layer flagged. Both `adopt` (existing files
  //    that will be overwritten) and `edit` (existing files we will overwrite
  //    post-merge) entries get archived so the user can always recover. We
  //    emit one tarball labelled "before-upgrade" — matching the legacy
  //    command's contract so existing restore tooling keeps working.
  //
  //    Wrapped in try/catch so a missing `tar` binary, full disk, or name
  //    collision produces a clean exit-1 instead of an unhandled rejection.
  //    On backup failure we must not proceed to the copy stage (the user
  //    has no recovery path otherwise) and the target is left untouched.
  const backupSet = decision.backup;
  let backupTarPath: string | null = null;
  if (backupSet.size > 0) {
    try {
      const backupResult = await createBackup(
        target,
        Array.from(backupSet).map((relPath) => ({ relPath })),
        "before-upgrade",
      );
      backupTarPath = backupResult.path;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      logger.error(`backup failed: ${message}`);
      logger.error(
        `no changes were made to ${target}; re-run once the issue is resolved`,
      );
      process.exitCode = 1;
      return;
    }
  }

  // 9-12. Apply changes, prune, run channel-specific work. Wrapped so any
  //       failure is surfaced cleanly with exit code 1 and the backup tarball
  //       left on disk for the user to inspect / restore manually.
  try {
    // 9. Apply modified + added by syncing each include subtree from assets.
    //    copyDir overwrites only files present in src, leaving extra files in
    //    dest alone — so user-added files survive unless --prune handles them
    //    explicitly below.
    //
    //    The filter combines three concerns:
    //    - codegraph subtree skips node_modules and package-lock.json (would
    //      be restored by `npm install` anyway and copying is slow).
    //    - The decision layer's `keep` set is skipped so user-modified
    //      interactive files are NOT overwritten by the recursive copy.
    //    - Files handled by `editResults` are skipped here because step 10
    //      writes the user-merged content over the top of whatever the copy
    //      would have produced.
    for (const inc of includes) {
      const source = resolveAsset(inc.pkgSubPath);
      const destination = join(target, inc.targetSubPath);
      const isCodegraph = inc.pkgSubPath === ".pi/extensions/codegraph";
      copyDir(source, destination, {
        filter: (_abs, rel) => {
          const targetRel = inc.targetSubPath ? `${inc.targetSubPath}/${rel}` : rel;
          if (isCodegraph && (rel === "node_modules" || rel === "package-lock.json")) return false;
          if (decision.keep.has(targetRel)) return false;
          if (decision.editResults.some((e) => e.relPath === targetRel)) return false;
          return true;
        },
        onSkip: (rel, reason) => logger.warn(`Skipped ${rel} (${reason})`),
      });
    }

    // 10. Write back user-edited files. The recursive copy in step 9 staged
    //     the new assets version; we overwrite with the user's edited
    //     content here. Atomic write so a crash mid-write cannot corrupt
    //     the file. `matchesTheirs === true` means the user opened the
    //     editor, saw the new content, and saved it verbatim — i.e. they
    //     effectively chose "Adopt new" via the editor.
    for (const ed of decision.editResults) {
      const abs = join(target, ed.relPath);
      ensureDir(dirname(abs));
      atomicWriteFile(abs, ed.content);
      logger.info(
        `wrote edited ${ed.relPath}${ed.matchesTheirs ? " (matches new version — merged)" : " (user edit kept)"}`,
      );
    }

    // 11. Handle removed files: walk the decision's `remove` set (which only
    //     contains user-confirmed deletions when --prune is in play).
    for (const relPath of decision.remove) {
      const abs = join(target, relPath);
      try {
        rmSync(abs, { force: true });
      } catch (error) {
        logger.warn(
          `Failed to prune ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
    }

    // 12. Channel-specific handling. codegraph npm install runs only when
    //     the extension payload actually changed AND we adopted/edited
    //     something under .pi/extensions/codegraph/. We consult the
    //     decision layer's sets (not the raw plan) so a "keep my codegraph
    //     override" choice does not trigger a npm install that would clobber
    //     the kept file via package.json's deps update.
    const codegraphNewlyEnabled = newChannels.codegraph && !state.channels.codegraph;
    const entireNewlyEnabled = newChannels.entire && !state.channels.entire;

    if (codegraphNewlyEnabled) {
      // installCodegraph does its own copy + npm install + codegraph init.
      // The copy we did in step 9 is redundant but harmless (writes the same
      // content) — we let installCodegraph own the full bootstrap.
      await installCodegraph(target, { logger });
    } else if (newChannels.codegraph) {
      const codegraphTouched =
        Array.from(decision.adopt).some((p) =>
          p.startsWith(".pi/extensions/codegraph/"),
        ) ||
        decision.editResults.some((e) => e.relPath.startsWith(".pi/extensions/codegraph/"));
      if (codegraphTouched) {
        await runNpmInstall(join(target, ".pi", "extensions", "codegraph"));
      }
    }

    if (entireNewlyEnabled) {
      await installEntire(target, { logger });
    }

    // 13. codegraph.json: only copy when the target lacks one. We never
    //     overwrite the user's existing config (respect their customisation).
    //     When codegraph is newly enabled, installCodegraph already handles
    //     this; we only need to run the check for the pre-existing case.
    if (newChannels.codegraph && !codegraphNewlyEnabled) {
      const configDest = join(target, "codegraph.json");
      if (!existsSync(configDest)) {
        const configSource = resolveAsset("codegraph.json");
        if (existsSync(configSource)) {
          copyFileSync(configSource, configDest);
          logger.info(`copied codegraph.json → ${configDest}`);
        }
      } else {
        logger.info("codegraph.json already present, keeping user copy");
      }
    }
  } catch (error) {
    logger.error(`upgrade failed: ${error instanceof Error ? error.message : String(error)}`);
    if (backupSet.size > 0) {
      logger.error(`backup retained on disk under .pi/.pisquad/backups/ for manual restore`);
    }
    process.exitCode = 1;
    return;
  }

  // 14. Persist new state. We always write the latest assets version —
  //     even when the user chose "keep my version" for some files, so
  //     the package-side baseline is still current. Per-user overrides
  //     reappear in the next diff because their hashes differ from the
  //     assets' hashes; the warning at the end reminds the user of that.
  writeState(target, {
    version: assetsVersion,
    cliVersion,
    channels: newChannels,
    lastUpgradedAt: new Date().toISOString(),
  });

  // 15. Summary.
  const keptInteractive = Array.from(decision.entries.values()).filter(
    (d) => d === "keep",
  ).length;
  printSummary({
    newChannels,
    backupCount: backupSet.size,
    backupPaths: backupTarPath === null ? [] : [backupTarPath],
    removedCount: decision.remove.size,
    pruned: options.prune === true,
    statePath: stateFile(target),
    modifiedCount: plan.modified.length,
    addedCount: plan.added.length,
    adoptedCount: decision.adopt.size,
    keptCount: keptInteractive,
    editedCount: decision.editResults.length,
  });
  if (keptInteractive > 0) {
    logger.warn(
      `kept ${keptInteractive} user modification(s) — they will reappear in next upgrade's diff`,
    );
  }
}

async function runNpmInstall(cwd: string): Promise<void> {
  try {
    await execFileAsync("npm", ["install", "--no-audit", "--no-fund", "--loglevel=warn"], {
      cwd,
      timeout: NPM_TIMEOUT_MS,
      maxBuffer: EXEC_MAX_BUFFER,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`npm install in ${cwd} failed: ${message}`);
  }
}

function printPlan(plan: DiffPlan, prune: boolean): void {
  logger.info(`modified (${plan.modified.length}):`);
  for (const m of plan.modified) logger.info(`  M ${m.relPath}`);
  logger.info(`added (${plan.added.length}):`);
  for (const a of plan.added) logger.info(`  A ${a.relPath}`);
  logger.info(`removed (${plan.removed.length}):`);
  for (const r of plan.removed) logger.info(`  D ${r.relPath}${prune ? " (will delete)" : " (will keep)"}`);
  logger.info(`unchanged (${plan.unchanged.length})`);
  if (prune && plan.removed.length > 0) {
    logger.info(`Pruning will also back up the ${plan.removed.length} removed file(s) before deletion.`);
  }
}

interface Summary {
  newChannels: Channels;
  backupCount: number;
  backupPaths: string[];
  removedCount: number;
  pruned: boolean;
  statePath: string;
  modifiedCount: number;
  addedCount: number;
  /** Number of files whose content was adopted from assets this run. */
  adoptedCount: number;
  /** Number of files the user explicitly chose to keep (interactive + --prune-deleted kept). */
  keptCount: number;
  /** Number of files the user edited in $EDITOR and wrote back. */
  editedCount: number;
}

function printSummary(s: Summary): void {
  const parts = ["core"];
  if (s.newChannels.codegraph) parts.push("codegraph");
  if (s.newChannels.entire) parts.push("entire");
  logger.info(`Channels: ${parts.join(" + ")}`);
  logger.info(`Modified: ${s.modifiedCount}, added: ${s.addedCount}`);
  logger.info(`Adopted: ${s.adoptedCount}, kept: ${s.keptCount}, edited: ${s.editedCount}`);
  if (s.removedCount > 0) {
    if (s.pruned) {
      logger.info(`Removed: ${s.removedCount} (pruned)`);
    } else {
      logger.info(`Removed: ${s.removedCount} (kept — pass --prune to delete)`);
    }
  }
  if (s.backupCount > 0) {
    logger.info(`Backup: ${s.backupCount} file(s) archived`);
    for (const p of s.backupPaths) logger.info(`  ${p}`);
  }
  logger.info(`State: ${s.statePath}`);
  logger.success("upgrade complete");
}

// ---- channel merging ---------------------------------------------------------

function parseChannelList(input: string | undefined): Set<Exclude<ChannelKey, "core">> {
  const out = new Set<Exclude<ChannelKey, "core">>();
  if (!input) return out;
  for (const raw of input.split(",")) {
    const v = raw.trim().toLowerCase();
    if (!v) continue;
    if (v === "codegraph" || v === "entire") out.add(v);
    else if (v !== "core") throw new Error(`Unknown channel: ${v}`);
  }
  return out;
}

/**
 * Merge `--with` / `--without` flags onto the state's existing channel set.
 *
 *   - state.channels is the baseline (no implicit changes).
 *   - `--with X` adds X to the baseline (idempotent).
 *   - `--without X` removes X from the baseline (idempotent).
 *   - `--with` and `--without` are mutually exclusive.
 *
 * `core` is always `true`; the schema pins it. The task spec uses this same
 * merge order so a later `pisquad upgrade --with codegraph` after a core-only
 * install adds the channel without re-prompting.
 */
function mergeChannels(base: Channels, options: { with?: string; without?: string }): Channels {
  const withSet = parseChannelList(options.with);
  const withoutSet = parseChannelList(options.without);
  if (withSet.size > 0 && withoutSet.size > 0) {
    throw new Error("Cannot combine --with and --without");
  }
  const next: Channels = {
    core: true,
    codegraph: base.codegraph,
    entire: base.entire,
  };
  if (withSet.size > 0) {
    for (const k of withSet) (next as unknown as Record<Exclude<ChannelKey, "core">, boolean>)[k] = true;
  }
  if (withoutSet.size > 0) {
    for (const k of withoutSet) (next as unknown as Record<Exclude<ChannelKey, "core">, boolean>)[k] = false;
  }
  return next;
}

import { copyDir } from "../copy.js";
import { resolveAsset } from "../paths.js";
import { atomicWriteFile } from "../fs-safe.js";
import { join } from "node:path";
import { existsSync } from "node:fs";
import type { PluginOptions } from "./types.js";

/**
 * Single source of truth for the core-channel extension set. Both the
 * `install` path (`installCore` below) and the `upgrade` path
 * (`src/commands/upgrade.ts` `includes` array) must derive their managed
 * includes from this set so a new core extension lands in both code paths
 * in lockstep. See ADR [[architecture/decisions/0004-subagent-suspension-arbitration.md]]
 * and the L4 contract in `docs/conventions/release-verification.md`.
 *
 * Entries are paths relative to `assets/.pi/` (i.e. the install root for
 * extensions). The upgrade pipeline prepends `.pi/` when projecting this
 * set into `PkgInclude` form.
 *
 * `bash-guard` is a core extension: it injects a 300s default timeout on
 * every bash tool call (so deadlocked sub-agents fail fast instead of
 * hanging the parent chain), and teaches the LLM via three complementary
 * surfaces when that default fires. It has no `node_modules` and ships
 * directly from `assets/.pi/extensions/bash-guard/index.ts`.
 *
 * Optional extensions (codegraph, entire) are NOT in this set: they are
 * copied by their own channel plugins (`installCodegraph`, `installEntire`)
 * so that `--yes` (core only) never copies code whose `node_modules` we
 * cannot ship.
 */
export const EXTENSION_DIRS = new Set([
  "extensions/subagent",
  "extensions/wikilink-lint",
  "extensions/bash-guard",
]);

/**
 * Copy the "core" payload (agents, skills, only the always-on extensions
 * subagent + wikilink-lint + bash-guard source trees).
 *
 * The optional codegraph / entire extensions are NOT copied here — they are
 * installed by their own channel plugins when the user passes `--with`. This
 * keeps the core payload stable per the PRD decision "core locked, codegraph /
 * entire optional", and avoids shipping codegraph source without its
 * `node_modules` (which would break `import typebox` at pi load time).
 */
export async function installCore(target: string, opts: PluginOptions): Promise<void> {
  const logger = opts.logger;
  const baseAsset = resolveAsset(".pi");

  const simpleDirs = ["agents", "skills"];
  for (const sub of simpleDirs) {
    const source = join(baseAsset, sub);
    const destination = join(target, ".pi", sub);
    if (!existsSync(source)) {
      logger.warn(`Skipping missing asset directory: ${source}`);
      continue;
    }
    if (opts.dryRun) {
      copyDir(source, destination, { dryRun: true });
    } else {
      copyDir(source, destination);
    }
    logger.info(`copied ${sub} → .pi/${sub}`);
  }

  // Docs payload lives at assets/docs/ and is part of the core channel
  // (always installed). Consumers treat <target>/docs/ as the documentation
  // library template — see docs/conventions/.
  const docsSource = resolveAsset("docs");
  const docsDestination = join(target, "docs");
  const onSkip = (rel: string, reason: string): void => logger.warn(`Skipped ${rel} (${reason})`);
  if (!existsSync(docsSource)) {
    logger.warn(`Skipping missing asset directory: ${docsSource}`);
  } else if (opts.dryRun) {
    copyDir(docsSource, docsDestination, { dryRun: true });
    logger.info(`[dry-run] copy docs → docs`);
  } else {
    copyDir(docsSource, docsDestination, { onSkip });
    logger.info(`copied docs → docs`);
  }

  for (const sub of EXTENSION_DIRS) {
    const source = join(baseAsset, sub);
    const destination = join(target, ".pi", sub);
    if (!existsSync(source)) {
      if (opts.dryRun) {
        logger.info(`[dry-run] skip missing: assets/.pi/${sub}`);
      } else {
        logger.warn(`Skipping missing asset directory: ${source}`);
      }
      continue;
    }
    const options: {
      filter: (_abs: string, rel: string) => boolean;
      dryRun?: boolean;
      onSkip?: (rel: string, reason: string) => void;
    } = {
      filter: (_abs: string, rel: string) => rel !== "node_modules" && rel !== "package-lock.json",
      onSkip: (rel: string, reason: string) => logger.warn(`Skipped ${rel} (${reason})`),
    };
    if (opts.dryRun) options.dryRun = true;
    copyDir(source, destination, options);
    logger.info(`copied ${sub} → .pi/${sub}`);
  }

  // Pin the .pi/.gitignore so users do not accidentally check node_modules in.
  const gitignorePath = join(target, ".pi", ".gitignore");
  if (opts.dryRun) {
    logger.info(`[dry-run] write ${gitignorePath}`);
  } else if (!existsSync(gitignorePath)) {
    atomicWriteFile(gitignorePath, "node_modules\n");
  }
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  mkdtempSync,
  existsSync,
  rmSync,
  readFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync } from "node:child_process";
import { upgradeCommand } from "../../src/commands/upgrade.js";
import { writeState } from "../../src/lib/version.js";
import { EXTENSION_DIRS } from "../../src/lib/plugins/core.js";
import type { Channels } from "../../src/lib/ui.js";
import type { DecisionDeps } from "../../src/upgrade/decision.js";

/**
 * L4 · Core extension manifest shipped via `pisquad upgrade`
 * ------------------------------------------------------------
 *
 * Mirror of `test/install/core-extension-manifest.test.ts`, but on the
 * upgrade path. The 0.3.1 bug was that `bash-guard` was listed in the
 * `install` channel manifest (`src/lib/plugins/core.ts`'s `EXTENSION_DIRS`)
 * but missing from the `upgrade` diff includes array
 * (`src/commands/upgrade.ts`). The result: a fresh `pisquad install` got
 * `bash-guard`; a `pisquad upgrade` from an older install did not —
 * silent degradation of the timeout safety net.
 *
 * This test pins the contract for the upgrade path:
 *   1. Seed an empty target with a state.json describing an OLD install
 *      (so the diff is non-trivial and the upgrade goes through copy).
 *   2. Call `upgradeCommand` in-process with fake `DecisionDeps` that
 *      answer "adopt" for every interactive entry and `noSelf: true`
 *      so we never hit the network.
 *   3. Assert every core extension (derived from `EXTENSION_DIRS` so
 *      a future addition to the source-of-truth is automatically
 *      covered) is physically present under `<target>/.pi/extensions/`.
 *   4. Sanity-check bash-guard source survived intact.
 *
 * Red/green proof (no git stash needed):
 *   - If `.pi/extensions/bash-guard` is removed from `EXTENSION_DIRS`
 *     OR from the derived includes in `src/commands/upgrade.ts`, this
 *     test fails on the `bash-guard/index.ts missing under target`
 *     assertion. The includes loop in `upgradeCommand` only copies
 *     what the diff plan contains, and the diff plan only contains
 *     what's in the includes array — so the regression is caught at
 *     the upgrade boundary, not three layers deeper inside
 *     `installCore` or `copyDir`.
 *
 * Why this lives next to `test/install/core-extension-manifest.test.ts`
 * but as an in-process test (not a `spawnSync(node dist/bin.js upgrade
 * ...)` test)?
 *   - `upgrade` requires an existing state.json + channels baseline,
 *     so it can't be spawned against a virgin tmp dir the way `install
 *     --yes` can. Driving `upgradeCommand` directly with injected
 *     `DecisionDeps` is the same pattern `test/upgrade/integration.test.ts`
 *     uses, so we lean on the established scaffolding.
 *   - The install-side test exercises the built binary (catch-all for
 *     CLI / main.ts / tsup regressions); this upgrade-side test
 *     exercises the in-process logic. Together they bracket the
 *     install → upgrade boundary from both sides.
 *
 * The test deliberately does NOT depend on the system `tar` binary:
 * when the target is empty and the upgrade adopts everything, no
 * existing files need backing up, so `createBackup` is never invoked.
 * This keeps the test runnable on hosts without tar.
 */

function makeTempTarget(): string {
  return mkdtempSync(join(tmpdir(), "pisquad-upgrade-manifest-"));
}

/**
 * Seed an "old" install: state.json with prior assets + CLI versions
 * so the upgrade has a non-trivial version diff to print and the
 * state-write stage exercises a real transition. The target itself
 * is otherwise empty — meaning every core extension entry will be
 * classified as `added` by `diffTree` and routed through the copy
 * stage (which is exactly the code path the bug bypassed).
 */
function seedOldInstall(target: string, channels: Channels): void {
  writeState(target, {
    version: "0.2.0",
    cliVersion: "0.2.0",
    channels,
  });
}

/**
 * Decision deps that auto-adopt everything and never open an editor.
 * Mirrors `test/upgrade/integration.test.ts`'s all-adopt spy.
 */
function makeAutoAdoptDeps(): DecisionDeps {
  return {
    promptStrategy: async () => "all-adopt",
    promptFileDecision: async () => "adopt",
    openEditor: async () => "",
  };
}

/**
 * List the core extension directory names by stripping the
 * `extensions/` prefix from each `EXTENSION_DIRS` entry. This makes the
 * assertion automatically cover any future addition to the
 * single-source-of-truth (subagent, wikilink-lint, bash-guard, ...).
 */
function coreExtensionNames(): string[] {
  return Array.from(EXTENSION_DIRS).map((sub) => sub.replace(/^extensions\//, ""));
}

describe("L4 · core extension manifest ships via upgrade", () => {
  it(
    "upgradeCommand lands every core extension at <target>/.pi/extensions/ after an old-version upgrade",
    async () => {
      const target = makeTempTarget();
      const channels: Channels = { core: true, codegraph: false, entire: false };
      seedOldInstall(target, channels);

      // Sanity: the production source-of-truth must already include the
      // three known core extensions. If a future refactor drops one,
      // this assertion fails first — before any upgrade runs — so the
      // failure message is unambiguous.
      const names = coreExtensionNames();
      for (const required of ["subagent", "wikilink-lint", "bash-guard"]) {
        assert.ok(
          names.includes(required),
          `EXTENSION_DIRS must include ${required}; got [${names.join(", ")}]`,
        );
      }

      const deps = makeAutoAdoptDeps();
      const prevExit = process.exitCode;
      process.exitCode = undefined;
      try {
        await upgradeCommand({
          target,
          prune: false,
          decisionDeps: deps,
          interactive: false,
          interactiveSetByUser: true,
          noSelf: true,
        });
      } finally {
        process.exitCode = prevExit;
      }

      // For each core extension, verify the directory + entry file
      // landed. This is the regression that motivated the test.
      const extRoot = join(target, ".pi", "extensions");
      for (const ext of names) {
        const entry = join(extRoot, ext, "index.ts");
        assert.equal(
          existsSync(entry),
          true,
          `${ext}/index.ts must ship under ${extRoot}/ after upgrade — ` +
            `regression: extension missing from upgrade includes array`,
        );
      }

      // Sanity check on the bash-guard copy specifically: its
      // `DEFAULT_BASH_TIMEOUT_S` constant must survive the round-trip
      // through `copyDir` so the upgraded copy is functional, not an
      // empty placeholder.
      const bashGuardSrc = join(extRoot, "bash-guard", "index.ts");
      const bashGuardContent = readFileSync(bashGuardSrc, "utf-8");
      assert.match(
        bashGuardContent,
        /DEFAULT_BASH_TIMEOUT_S/,
        "bash-guard source must contain its timeout constant after upgrade",
      );

      // Cleanup. Use rmSync with recursive to ensure nested dirs
      // (.pi/extensions/bash-guard, .pi/.pisquad, ...) are gone.
      rmSync(target, { recursive: true, force: true });
    },
  );

  it(
    "upgradeCommand lands every core extension even with --interactive + tty (managed path is non-interactive regardless)",
    async () => {
      // Defence in depth: the previous test exercises the
      // all-adopt / non-interactive branch. This test exercises the
      // --interactive + tty branch (forced via `forceInteractiveEnv`)
      // to make sure the per-file interactive loop also leaves the
      // core extensions alone — they are managed, so they must be
      // auto-adopted regardless of what the user picks for the
      // interactive files.
      //
      // We still skip the test on hosts without `tar`: an empty
      // target still goes through the decision layer, which doesn't
      // call createBackup; the only tar dependency would be if
      // somewhere along the way a backup kicks in (it doesn't here).
      // We borrow the integration test's `tarAvailable()` check so
      // the two suites stay aligned on what's runnable where.
      if (!tarAvailable()) return;
      const target = makeTempTarget();
      const channels: Channels = { core: true, codegraph: false, entire: false };
      seedOldInstall(target, channels);

      // Interactive deps that pick "keep" for every interactive file.
      // Managed extensions must still be auto-resolved.
      const deps: DecisionDeps = {
        promptStrategy: async () => "per-file",
        promptFileDecision: async () => "keep",
        openEditor: async () => "",
      };

      const prevExit = process.exitCode;
      process.exitCode = undefined;
      try {
        await upgradeCommand({
          target,
          prune: false,
          decisionDeps: deps,
          interactive: true,
          interactiveSetByUser: true,
          forceInteractiveEnv: true,
          noSelf: true,
        });
      } finally {
        process.exitCode = prevExit;
      }

      const extRoot = join(target, ".pi", "extensions");
      for (const ext of coreExtensionNames()) {
        assert.equal(
          existsSync(join(extRoot, ext, "index.ts")),
          true,
          `${ext}/index.ts must land even when interactive mode is forced and user picks "keep" everywhere`,
        );
      }

      rmSync(target, { recursive: true, force: true });
    },
  );
});

/** Local copy of the integration test's tar probe — kept here so the
 * two suites don't drift on what counts as a "skip" host. */
function tarAvailable(): boolean {
  try {
    execSync("tar --version", { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  statSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { spawnSync } from "node:child_process";

/**
 * L4 · Core extension manifest shipped via `pisquad install`
 * ------------------------------------------------------------
 *
 * The core channel advertises three always-on extensions: subagent,
 * wikilink-lint, and bash-guard. The first two have been on the manifest
 * since the CLI shipped; bash-guard was promoted to "core" in 0.3.0
 * (alongside the idle-suspension arbitration work) and the install
 * manifest in `src/lib/plugins/core.ts` (`EXTENSION_DIRS`) was missed.
 *
 * Without bash-guard in the manifest, `pisquad install --yes` lands a
 * target whose `.pi/extensions/` only contains subagent + wikilink-lint.
 * A consumer who then runs the agent sees no timeout hints on bash
 * tool calls and no system-prompt runtime note about the default —
 * silently degrading the safety net that the 0.3.0 release notes
 * promised.
 *
 * This test pins the contract end-to-end:
 *   1. Spawn the freshly-built `dist/bin.js install --yes <tmp-target>`.
 *   2. Assert the three core extensions are physically present under
 *      `<tmp-target>/.pi/extensions/`.
 *   3. Sanity-check the bash-guard source survived the copy intact
 *      (its `DEFAULT_BASH_TIMEOUT_S` constant is in the file).
 *
 * Why exercise the built binary instead of importing `installCore`
 * from src/?
 *   - It catches the full production path: CLI argv parsing → main.ts
 *     dispatch → installCommand → installCore → copyDir. A regression
 *     in any layer (e.g. someone refactors main.ts and accidentally
 *     drops the `--yes` short-circuit, or the tsup bundle stops
 *     embedding the assets lookup) flips this test red.
 *   - The user constraint says "L4 测试用的 dist 必须是新鲜构建", so
 *     the test reads `process.cwd()/dist/bin.js` and refuses to fall
 *     back to tsx — keeping the red/green logic honest.
 *
 * Red/green proof (no git stash needed):
 *   - If `extensions/bash-guard` is removed from `EXTENSION_DIRS` in
 *     `src/lib/plugins/core.ts`, the install loop in `installCore`
 *     iterates only `subagent` + `wikilink-lint`. The first assertion
 *     below fails with `bash-guard/index.ts missing under target`,
 *     making the regression visible at the install boundary — not
 *     three layers deeper inside `installCore`.
 *   - Conversely, with bash-guard restored, all three assertions pass.
 *
 * Why a dedicated test/install/ dir?
 *   - The integration test under `test/upgrade/` exercises the
 *     upgrade decision layer (DecisionDeps). It never spawns the
 *     dist binary. Putting L4 in its own directory makes the contract
 *     discoverable: anything under `test/install/` runs the built CLI.
 */

function resolveDistBin(): string {
  const binPath = resolve(process.cwd(), "dist", "bin.js");
  if (!existsSync(binPath)) {
    throw new Error(
      `dist/bin.js not found at ${binPath}. Run \`npm run build\` first; L4 requires a fresh build.`,
    );
  }
  const stat = statSync(binPath);
  if (!stat.isFile()) {
    throw new Error(`dist/bin.js exists but is not a regular file: ${binPath}`);
  }
  return binPath;
}

/** Spawn `node dist/bin.js install --yes <target>` and capture stdout+stderr. */
function runInstall(target: string): { status: number; stdout: string; stderr: string } {
  const bin = resolveDistBin();
  const result = spawnSync(process.execPath, [bin, "install", "--yes", target], {
    encoding: "utf-8",
    timeout: 60_000,
    env: { ...process.env, NO_COLOR: "1" },
  });
  return {
    status: result.status ?? -1,
    stdout: result.stdout ?? "",
    stderr: result.stderr ?? "",
  };
}

describe("L4 · core extension manifest ships via install --yes", () => {
  it("copies subagent, wikilink-lint, and bash-guard into <target>/.pi/extensions/", () => {
    const target = mkdtempSync(join(tmpdir(), "pisquad-l4-manifest-"));
    let proc: ReturnType<typeof runInstall> | undefined;
    try {
      proc = runInstall(target);

      // Sanity: install must exit 0. A non-zero status would mask the
      // assertion failures below (e.g. missing assets dir would throw
      // inside copyDir). Surface it first so the test message is
      // actionable.
      assert.equal(
        proc.status,
        0,
        `pisquad install --yes must exit 0\nstdout: ${proc.stdout}\nstderr: ${proc.stderr}`,
      );

      const extRoot = join(target, ".pi", "extensions");
      assert.equal(existsSync(extRoot), true, ".pi/extensions/ must exist after install");

      // The two pre-existing core extensions — these are control
      // assertions to make sure the test isn't satisfied by a no-op
      // install (e.g. dry-run leaking through).
      for (const ext of ["subagent", "wikilink-lint"]) {
        assert.equal(
          existsSync(join(extRoot, ext, "index.ts")),
          true,
          `core extension "${ext}" must ship under ${extRoot}/`,
        );
      }

      // The new entry — this is the regression that motivated L4.
      const bashGuardPath = join(extRoot, "bash-guard", "index.ts");
      assert.equal(
        existsSync(bashGuardPath),
        true,
        `bash-guard extension must ship under ${extRoot}/ (regression: EXTENSION_DIRS missed this entry in 0.3.0)`,
      );

      // Source content survived the copy intact. If someone replaces
      // the asset tree with a placeholder, this fails loudly.
      const content = readFileSync(bashGuardPath, "utf-8");
      assert.match(
        content,
        /DEFAULT_BASH_TIMEOUT_S/,
        "bash-guard source must contain its timeout constant — copy may have corrupted the file",
      );
    } finally {
      rmSync(target, { recursive: true, force: true });
      // Surface proc for any test runner that captures locals.
      void proc;
    }
  });
});

