+	let entries: SubagentJsonlEntry[];
+	try {
+		entries = await parseSubagentEntries(sessionFile);
+	} catch (err) {
+		const msg = err instanceof Error ? err.message : String(err);
+		return {
+			content: [
+				{
+					type: "text",
+					text: `[transcript] 解析会话文件失败：${msg}\n文件路径：${sessionFile}`,
+				},
+			],
+			details: _makeDetails("single")([]),
+		};
+	}
+
+	const picked = pickSubagentEntry(entries, transcriptParams);
+	if (picked.kind !== "found") {
+		const text =
+			picked.kind === "no_matches"
+				? transcriptFailureText("no_matches", transcriptParams, entries, picked)
+				: transcriptFailureText("index_out_of_range", transcriptParams, entries, picked);
+		return {
+			content: [{ type: "text", text }],
+			details: _makeDetails("single")([]),
+		};
+	}
+
+	const text = renderTranscript(picked.entry, transcriptParams);
+	return {
+		content: [{ type: "text", text }],
+		// Mirror the mode of the matched entry so the TUI renderer
+		// picks the right branch (single / parallel / chain). For
+		// the transcript call we pass an empty results array — the
+		// `details` field is informational only (the text payload
+		// carries the actual transcript) and the renderer treats
+		// empty results + non-zero suspensions/no suspensions the
+		// same way it does for the normal completion path.
+		details: _makeDetails(picked.entry.mode)(picked.entry.results),
+	};
