/**
 * C1 regression test: renderResult must not crash on a
 * non-suspended (normal-exit) result.
 *
 * Background
 * ----------
 * The headline C1 bug was that the renderer's early-return guard
 * read `details.suspensions.length` without an existence check,
 * but the `SubagentDetails` type did not declare the `suspensions`
 * field — the `makeDetails` factory in production code DID populate
 * it, but a future shape change could omit it and every render of
 * a normal-exit result would throw `TypeError: Cannot read
 * properties of undefined (reading 'length')`.
 *
 * This file:
 *   - registers the real extension against a mock `pi` object,
 *     capturing the registered tool definition;
 *   - invokes `renderResult` with a synthetic non-suspended
 *     `AgentToolResult` (mode=single, results=[one], suspensions=[])
 *     using a stub theme + context;
 *   - asserts the renderer returns a non-null TUI element rather
 *     than throwing.
 *
 * The "factory shape" half of C1 is covered by `details.test.ts`;
 * this file is the half that exercises the real renderer with a
 * real (no-suspensions) result, so any future regression that
 * drops `suspensions` from the factory or short-circuits the
 * renderer on `undefined` fails loudly here.
 *
 * Test mechanics
 * --------------
 * We spawn a one-shot Node child process (mirroring the e2e
 * pattern) because importing the extension registers a
 * `process.on("exit")` listener via `parentProcessCleanup` that we
 * don't want accumulating across `node --test` runs. A child
 * process is the cleanest way to scope that side effect.
 */
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { writeFileSync, unlinkSync } from "node:fs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = join(__dirname, "..", "..");

interface RenderResult {
	scenario: string;
	ok: boolean;
	error?: string;
	renderedKind?: string;
	renderedText?: string;
}

/** Spawn a tiny script that imports the extension, captures the
 *  tool, and calls renderResult with a non-suspended result.
 *  Returns the parsed JSON. */
function probe(): RenderResult {
	const driverSrc = `
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const mod = await import("${join(PROJECT_ROOT, ".pi/extensions/subagent/index.ts").replace(/\\\\/g, "/")}");
const extensionFn = (mod as { default: (pi: ExtensionAPI) => unknown }).default;

let captured: any = null;
const pi: ExtensionAPI = {
  registerTool: (def) => { captured = def; },
  getAllTools: () => [],
} as unknown as ExtensionAPI;

await extensionFn(pi);
if (!captured) {
  process.stdout.write(JSON.stringify({ scenario: "renderResult", ok: false, error: "no tool captured" }) + "\\n");
  process.exit(0);
}

// Build a synthetic NON-suspended result -- this is the shape
// that makeDetails("single")([])([singleResult]) returns in
// production.
const singleResult = {
  agent: "test-agent",
  agentSource: "project",
  task: "do a thing",
  exitCode: 0,
  messages: [
    {
      role: "assistant",
      content: [{ type: "text", text: "all done" }],
      model: "test-model",
      api: "openai-responses",
      provider: "openai",
      usage: { input: 1, output: 2, cacheRead: 0, cacheWrite: 0, cost: { total: 0 }, totalTokens: 3 },
      stopReason: "stop",
      timestamp: 0,
    },
  ],
  stderr: "",
  usage: { input: 1, output: 2, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 3, turns: 1 },
  model: "test-model",
  stopReason: "stop",
};

const result = {
  content: [{ type: "text", text: "all done" }],
  details: {
    mode: "single",
    agentScope: "both",
    projectAgentsDir: null,
    results: [singleResult],
    suspensions: [], // <- the field that used to be missing
  },
};

// Minimal TUI theme stub: every method returns its string arg.
// renderResult only reads theme.fg() and theme.bold(), so this
// is enough to exercise the renderer without pulling in the real
// theme machinery.
const theme = {
  fg: (_color: any, text: string) => text,
  bold: (text: string) => text,
  muted: (text: string) => text,
  dim: (text: string) => text,
  accent: (text: string) => text,
  toolTitle: (text: string) => text,
  success: (text: string) => text,
  error: (text: string) => text,
  warning: (text: string) => text,
  toolOutput: (text: string) => text,
};

try {
  const rendered = captured.renderResult(result, { expanded: false }, theme, {});
  process.stdout.write(JSON.stringify({
    scenario: "renderResult",
    ok: rendered !== null && rendered !== undefined,
    renderedKind: typeof rendered,
    renderedText: typeof rendered?.text === "string" ? rendered.text.slice(0, 200) : "(non-text)",
  }) + "\\n");
} catch (e) {
  process.stdout.write(JSON.stringify({
    scenario: "renderResult",
    ok: false,
    error: (e as Error).message,
  }) + "\\n");
}
`;
	const driverPath = join(PROJECT_ROOT, ".pi/extensions/subagent/_c1_regression.mts");
	writeFileSync(driverPath, driverSrc, "utf8");
	try {
		const proc = spawnSync(process.execPath, ["--import", "tsx/esm", driverPath], {
			cwd: PROJECT_ROOT,
			env: {
				...process.env,
				TSX_TSCONFIG_PATH: join(PROJECT_ROOT, "tsconfig.test-runtime.json"),
			},
			encoding: "utf8",
		});
		if (proc.status !== 0) {
			return {
				scenario: "renderResult",
				ok: false,
				error: `probe exited with code ${proc.status}\nstderr: ${proc.stderr?.slice(0, 500)}`,
			};
		}
		const line = (proc.stdout ?? "").trim().split("\n").pop() ?? "";
		return JSON.parse(line) as RenderResult;
	} finally {
		try {
			unlinkSync(driverPath);
		} catch {
			/* ignore */
		}
	}
}

describe("renderResult regression (C1)", () => {
	it("does not crash on a non-suspended (mode=single, suspensions=[]) result", () => {
		const r = probe();
		assert.ok(r.ok, `renderResult failed: ${r.error}`);
		// The stub theme echoes strings, so we expect the
		// "all done" final-output text somewhere in the rendered
		// payload.
		if (r.renderedText) {
			assert.match(r.renderedText, /all done/);
		}
	});
});

/**
 * Unit tests for the `makeDetails` factory's shape contract.
 *
 * `makeDetails` (defined inside the registered tool closure in
 * `index.ts`) is the single source of truth for the `details`
 * payload that travels through `AgentToolResult`. The whole
 * tool-rendering path depends on the factory always populating
 * `suspensions` (defaulting to `[]`), since `renderResult` reads
 * `details.suspensions.length` without an existence check on the
 * normal-result path. A regression there was the headline C1 bug.
 *
 * We re-implement the factory here for testability (the original is
 * a closure private to `execute()`) and run it through the same
 * assertions we want to guarantee.
 *
 * Coverage:
 *   - `suspensions` defaults to `[]` when omitted
 *   - `suspensions` defaults to `[]` when explicitly null/undefined
 *   - `suspensions` round-trips when provided
 *   - Returned shape has all three fields populated for non-suspended
 *     results (no `undefined` holes)
 *   - The shape is structurally compatible with `renderResult`'s
 *     `(details.results.length === 0 && details.suspensions.length === 0)`
 *     early-return (a normal exit with one result + empty
 *     suspensions must NOT trigger the early-return — that was C1's
 *     regression: a TypeError when `suspensions` was undefined).
 */
import { describe, it } from "node:test";
import assert from "node:assert/strict";

/** Mirror of `SingleResult` from index.ts (kept local to avoid
 *  pulling the whole extension module just for typing). */
interface SingleResultLike {
	agent: string;
	agentSource: string;
	task: string;
	exitCode: number;
	messages: any[];
	stderr: string;
	usage: Record<string, number | string>;
	step?: number;
}

interface SubagentDetailsLike {
	mode: "single" | "parallel" | "chain";
	agentScope: string;
	projectAgentsDir: string | null;
	results: SingleResultLike[];
	suspensions: Array<{ suspensionId: string }>;
}

interface SuspendedSnapshotLike extends SubagentDetailsLike {}

/** A copy of the factory shape from `.pi/extensions/subagent/index.ts`.
 *  Kept in lockstep — when the factory changes, change here too.
 *  This is intentional duplication so we can unit-test the contract
 *  without booting the whole extension. */
function makeDetails(
	mode: "single" | "parallel" | "chain",
	agentScope: string,
	projectAgentsDir: string | null,
): (
	results: SingleResultLike[],
	suspensions?: SubagentDetailsLike["suspensions"],
) => SubagentDetailsLike | SuspendedSnapshotLike {
	return (results, suspensions) => {
		return {
			mode,
			agentScope,
			projectAgentsDir,
			results,
			suspensions: suspensions ?? [],
		};
	};
}

function fixtureResult(agent: string): SingleResultLike {
	return {
		agent,
		agentSource: "user",
		task: `task for ${agent}`,
		exitCode: 0,
		messages: [],
		stderr: "",
		usage: { input: 0, output: 0 },
	};
}

describe("makeDetails factory contract", () => {
	it("always populates `suspensions` (defaults to [])", () => {
		const f = makeDetails("single", "both", null);
		const details = f([fixtureResult("a")]);
		assert.ok(details.suspensions, `suspensions field missing`);
		assert.ok(Array.isArray(details.suspensions));
		assert.equal(details.suspensions.length, 0);
	});

	it("treats undefined suspensions identically to empty", () => {
		const f = makeDetails("single", "both", null);
		const a = f([fixtureResult("a")]);
		const b = f([fixtureResult("a")], undefined);
		assert.deepEqual(a, b);
	});

	it("returns the supplied suspensions verbatim", () => {
		const f = makeDetails("parallel", "user", "/tmp/.pi");
		const sups = [{ suspensionId: "susp_1_aabbcc" }, { suspensionId: "susp_2_ddeeff" }];
		const details = f([fixtureResult("a"), fixtureResult("b"), fixtureResult("c")], sups);
		assert.equal(details.suspensions, sups);
		assert.equal(details.suspensions.length, 2);
	});

	it("non-suspended result has the same SHAPE as a suspended one (no undefined fields)", () => {
		// `renderResult` checks `(details.results.length === 0 && details.suspensions.length === 0)`.
		// A normal (non-suspended) result with one task MUST have a
		// defined `suspensions` array of length 0, otherwise the
		// renderer's `details.suspensions.length` access throws.
		const f = makeDetails("single", "both", null);
		const details = f([fixtureResult("a")]);
		assert.equal(details.mode, "single");
		assert.equal(details.agentScope, "both");
		assert.equal(details.projectAgentsDir, null);
		assert.equal(details.results.length, 1);
		// The whole point of the C1 regression: this `.length` access
		// must not throw.
		assert.equal(details.suspensions.length, 0);
	});

	it("an empty results array AND empty suspensions array is the renderer's 'no output' signal", () => {
		// Render path contract: when both `results` and
		// `suspensions` are empty, the renderer falls back to the
		// first content block rather than trying to format
		// anything. This test asserts both are array-shaped.
		const f = makeDetails("single", "both", null);
		const details = f([]);
		assert.equal(details.results.length, 0);
		assert.equal(details.suspensions.length, 0);
	});

	it("mode is preserved across the factory (chain/parallel/single)", () => {
		const single = makeDetails("single", "both", null)([fixtureResult("x")]);
		const parallel = makeDetails("parallel", "both", null)([fixtureResult("x")]);
		const chain = makeDetails("chain", "both", null)([fixtureResult("x")]);
		assert.equal(single.mode, "single");
		assert.equal(parallel.mode, "parallel");
		assert.equal(chain.mode, "chain");
	});
});

describe("Suspension re-freeze flow (handleResume 2nd freeze path)", () => {
	// The C2 fix asserts that a parallel Job's `tasks` field is
	// present so the resume path can rebuild a length-N ordered
	// result array. We test the merge logic directly.

	it("Job.parallel carries the full original task list (C2 fix)", () => {
		interface TaskSpec {
			agent: string;
			task: string;
		}
		interface JobParallel {
			kind: "parallel";
			tasks: TaskSpec[];
			index: number;
			completedResults: Array<{ agent: string }>;
		}

		const tasks: TaskSpec[] = [
			{ agent: "a", task: "ta" },
			{ agent: "b", task: "tb" },
			{ agent: "c", task: "tc" },
		];
		const job: JobParallel = {
			kind: "parallel",
			tasks,
			index: 1, // task at index 1 was the one suspended
			// completedResults MUST exclude the suspended index.
			completedResults: [{ agent: "a" }, { agent: "c" }],
		};

		// Replicate the resume-time merge logic from index.ts.
		function mergeParallel(
			job: JobParallel,
			resumedResult: { agent: string },
		): Array<{ agent: string } | undefined> {
			const merged: Array<{ agent: string } | undefined> = new Array(job.tasks.length);
			let cursor = 0;
			for (let i = 0; i < job.tasks.length; i++) {
				if (i === job.index) {
					merged[i] = resumedResult;
				} else {
					merged[i] = job.completedResults[cursor++]!;
				}
			}
			return merged;
		}

		const resumed = { agent: "b-result" };
		const merged = mergeParallel(job, resumed);
		assert.equal(merged.length, 3, `merge length must match tasks length`);
		assert.equal(merged[0]!.agent, "a");
		assert.equal(merged[1]!.agent, "b-result");
		assert.equal(merged[2]!.agent, "c");
	});

	it("Suspension.activeAbortHandler tracks the live handler (C3 fix)", () => {
		// C3 fix: the `activeAbortHandler` field on `Suspension`
		// holds the function reference we registered via
		// `attachSignalListener` so subsequent freeze paths can
		// detach exactly that reference. This test models the
		// flow.
		interface Handler {
			(): void;
		}

		// Resume-then-freeze flow.
		const handlers: (Handler | null)[] = [null];
		// First attach: store ref.
		const h1 = () => {};
		handlers[0] = h1;
		// Second freeze: detach THAT ref, replace with new.
		const detached = handlers[0];
		const h2 = () => {};
		handlers[0] = h2;
		// The detacher must receive the *original* handler.
		assert.equal(detached, h1, "detach must use the handler that was registered, not null");
		// And the new handler is now active.
		assert.equal(handlers[0], h2);
	});
});

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  statSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { spawnSync } from "node:child_process";

/**
 * L4 · Core extension manifest shipped via `pisquad install`
 * ------------------------------------------------------------
 *
 * The core channel advertises three always-on extensions: subagent,
 * wikilink-lint, and bash-guard. The first two have been on the manifest
 * since the CLI shipped; bash-guard was promoted to "core" in 0.3.0
 * (alongside the idle-suspension arbitration work) and the install
 * manifest in `src/lib/plugins/core.ts` (`EXTENSION_DIRS`) was missed.
 *
 * Without bash-guard in the manifest, `pisquad install --yes` lands a
 * target whose `.pi/extensions/` only contains subagent + wikilink-lint.
 * A consumer who then runs the agent sees no timeout hints on bash
 * tool calls and no system-prompt runtime note about the default —
 * silently degrading the safety net that the 0.3.0 release notes
 * promised.
 *
 * This test pins the contract end-to-end:
 *   1. Spawn the freshly-built `dist/bin.js install --yes <tmp-target>`.
 *   2. Assert the three core extensions are physically present under
 *      `<tmp-target>/.pi/extensions/`.
 *   3. Sanity-check the bash-guard source survived the copy intact
 *      (its `DEFAULT_BASH_TIMEOUT_S` constant is in the file).
 *
 * Why exercise the built binary instead of importing `installCore`
 * from src/?
 *   - It catches the full production path: CLI argv parsing → main.ts
 *     dispatch → installCommand → installCore → copyDir. A regression
 *     in any layer (e.g. someone refactors main.ts and accidentally
 *     drops the `--yes` short-circuit, or the tsup bundle stops
 *     embedding the assets lookup) flips this test red.
 *   - The user constraint says "L4 测试用的 dist 必须是新鲜构建", so
 *     the test reads `process.cwd()/dist/bin.js` and refuses to fall
 *     back to tsx — keeping the red/green logic honest.
 *
 * Red/green proof (no git stash needed):
 *   - If `extensions/bash-guard` is removed from `EXTENSION_DIRS` in
 *     `src/lib/plugins/core.ts`, the install loop in `installCore`
 *     iterates only `subagent` + `wikilink-lint`. The first assertion
 *     below fails with `bash-guard/index.ts missing under target`,
 *     making the regression visible at the install boundary — not
 *     three layers deeper inside `installCore`.
 *   - Conversely, with bash-guard restored, all three assertions pass.
 *
 * Why a dedicated test/install/ dir?
 *   - The integration test under `test/upgrade/` exercises the
 *     upgrade decision layer (DecisionDeps). It never spawns the
 *     dist binary. Putting L4 in its own directory makes the contract
 *     discoverable: anything under `test/install/` runs the built CLI.
 */

function resolveDistBin(): string {
  const binPath = resolve(process.cwd(), "dist", "bin.js");
  if (!existsSync(binPath)) {
    throw new Error(
      `dist/bin.js not found at ${binPath}. Run \`npm run build\` first; L4 requires a fresh build.`,
    );
  }
  const stat = statSync(binPath);
  if (!stat.isFile()) {
    throw new Error(`dist/bin.js exists but is not a regular file: ${binPath}`);
  }
  return binPath;
}

/** Spawn `node dist/bin.js install --yes <target>` and capture stdout+stderr. */
function runInstall(target: string): { status: number; stdout: string; stderr: string } {
  const bin = resolveDistBin();
  const result = spawnSync(process.execPath, [bin, "install", "--yes", target], {
    encoding: "utf-8",
    timeout: 60_000,
    env: { ...process.env, NO_COLOR: "1" },
  });
  return {
    status: result.status ?? -1,
    stdout: result.stdout ?? "",
    stderr: result.stderr ?? "",
  };
}

describe("L4 · core extension manifest ships via install --yes", () => {
  it("copies subagent, wikilink-lint, and bash-guard into <target>/.pi/extensions/", () => {
    const target = mkdtempSync(join(tmpdir(), "pisquad-l4-manifest-"));
    let proc: ReturnType<typeof runInstall> | undefined;
    try {
      proc = runInstall(target);

      // Sanity: install must exit 0. A non-zero status would mask the
      // assertion failures below (e.g. missing assets dir would throw
      // inside copyDir). Surface it first so the test message is
      // actionable.
      assert.equal(
        proc.status,
        0,
        `pisquad install --yes must exit 0\nstdout: ${proc.stdout}\nstderr: ${proc.stderr}`,
      );

      const extRoot = join(target, ".pi", "extensions");
      assert.equal(existsSync(extRoot), true, ".pi/extensions/ must exist after install");

      // The two pre-existing core extensions — these are control
      // assertions to make sure the test isn't satisfied by a no-op
      // install (e.g. dry-run leaking through).
      for (const ext of ["subagent", "wikilink-lint"]) {
        assert.equal(
          existsSync(join(extRoot, ext, "index.ts")),
          true,
          `core extension "${ext}" must ship under ${extRoot}/`,
        );
      }

      // The new entry — this is the regression that motivated L4.
      const bashGuardPath = join(extRoot, "bash-guard", "index.ts");
      assert.equal(
        existsSync(bashGuardPath),
        true,
        `bash-guard extension must ship under ${extRoot}/ (regression: EXTENSION_DIRS missed this entry in 0.3.0)`,
      );

      // Source content survived the copy intact. If someone replaces
      // the asset tree with a placeholder, this fails loudly.
      const content = readFileSync(bashGuardPath, "utf-8");
      assert.match(
        content,
        /DEFAULT_BASH_TIMEOUT_S/,
        "bash-guard source must contain its timeout constant — copy may have corrupted the file",
      );
    } finally {
      rmSync(target, { recursive: true, force: true });
      // Surface proc for any test runner that captures locals.
      void proc;
    }
  });
});

