export function previewToolCallArgs(name: string, args: Record<string, unknown>): string {
	const cap = (s: string) => {
		const flat = s.replace(/\s+/g, " ").trim();
		return flat.length > TRANSCRIPT_ARG_PREVIEW_LEN
			? `${flat.slice(0, TRANSCRIPT_ARG_PREVIEW_LEN)}...`
			: flat;
