		case "bash": {
			const cmd = typeof args.command === "string" ? args.command : "";
			return cap(cmd);
		}
		case "read":
		case "write":
		case "edit": {
			const p = args.file_path ?? args.path;
			return cap(typeof p === "string" ? p : "");
		}
		default: {
			try {
				return cap(JSON.stringify(args));
			} catch {
				return cap(String(args));
			}
		}
	}
