+	const agentPart = opts.agent ? `, agent='${opts.agent}'` : "";
+	const onlyPart = only === "interrupted" ? "（含 suspended 快照的）" : "（全部）";
+	if (kind === "no_matches") {
+		const seenAgents = Array.from(new Set(allEntries.flatMap((e) => e.results.map((r) => r.agent)))).sort();
