		);
		for (const symbol of [
			"getContextWindowFor",
			"appendUsageLines",
			"aggregateUsageToUsage",
			"usageLine",
			"previewToolCallArgs",
			"previewTextBlock",
			"__resetModelsStoreForTests",
			"pickSubagentEntry",
			"renderTranscript",
			"parseSubagentEntries",
			"isInterruptedEntry",
		]) {
			assert.match(
				src,
				new RegExp(`export\\s+(?:async\\s+)?function\\s+${symbol}\\b`),
				`${symbol} must be exported from subagent/index.ts`,
			);
		}
	});
});

